llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Omadacycline, a closely related tetracycline with the same core scaffold, has an absolute oral bioavailability of 34.5% in healthy adults under fasting conditions, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Tetracycline itself has an oral bioavailability of 75% in humans, demonstrating that the highly polar tetracycline core can be well absorbed orally despite unfavorable physicochemical predictions.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Idarubicin, a polar ionizable anthracycline, has a median oral bioavailability of 29% in patients, showing that high polarity and ionization do not preclude F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Sulpiride, a zwitterionic sulfonamide with low permeability, has an oral bioavailability of 27–30% in humans, supporting that zwitterionic/fully ionized molecules can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Apixaban has an absolute oral bioavailability of about 49–50% in humans despite being a P-gp substrate with a challenging physicochemical profile, supporting achievable F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Loperamide has an absolute oral bioavailability of 0.3% in humans due to P-gp efflux and first-pass metabolism; if the query shares strong P-gp efflux, this would argue for low F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Butorphanol has an oral bioavailability of about 5% due to extensive first-pass metabolism, providing a low-F counterexample among high-transfer analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest experimental analogues—especially omadacycline (34.5%) and tetracycline (75%)—show that the tetracycline scaffold can achieve oral bioavailability ≥20% despite high polarity, high TPSA, and zwitterionic character. Additional polar/ionizable drugs such as idarubicin, sulpiride, and apixaban also exceed 20%. The low-F analogues (loperamide, butorphanol) are mechanistically distinct and outweighed by class-specific evidence. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself is included; the closest evidence is from omadacycline and tetracycline.",
    "Food effects can drastically reduce tetracycline bioavailability (e.g., omadacycline F ~0.6% after a high-fat meal), and the query's dosing/fed state is unspecified.",
    "The query's P-gp/efflux liability relative to loperamide is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

